def read(name):
    with gzip.open(BASE/name,'rt',encoding='utf8') as stream:
        return [json.loads(line) for line in stream]

def dump(path, value):
    path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf8')

def main():
    OUT.mkdir(parents=True,exist_ok=True)
    rows=read('OWNER1321_EXACT_CONTENT.audit.jsonl.gz')
    pending={row['owner_id'] for row in read('OWNER1321_DISPOSITION09.jsonl.gz') if row['processing_disposition']=='HOLD_NEEDS_SEMANTIC_REVIEW'}
    lookup={(row['episode_id'],row['source_message_index']):row for row in rows if row['owner_id'] in pending}
    contexts={row['episode_id']:row for row in read('ORIGINAL_CONTEXTS_343.audit.jsonl.gz')}
    reviews=[]
    names={'C':'CONTEXT_ONLY_AFTER_CONTENT_REVIEW','H':'HOLD_SPECIFIC_CONTENT_OR_EVIDENCE_DEFECT','P':'SCOPED_VALIDATION_ACTION_CANDIDATE_PENDING_ROOT_QA'}
    for episode, notes in REVIEWS.items():
        for index, disposition, reason, evidence in notes:
            row=lookup[(episode,index)]
            context=contexts[episode]
            result={
                'owner_id':row['owner_id'],'episode_id':episode,'route_id':row['route_id'],
                'source_ids':row['source_ids'],'source_message_index':index,
                'original_target_sha256_sorted':row['target_original_SHA256_sorted'],
                'review_disposition':names[disposition],'concrete_reason':reason,
                'review_scope':'Original task plus target action/public text and cited causal observations; identified defect suffices to hold. Long business/code body not claimed wholly semantically verified.',
                'reviewer':'Codex_process09_content_review','original_native_R_admitted':False,
                'context_archive':'../ORIGINAL_CONTEXTS_343.audit.jsonl.gz',
                'original_action_archive':'../OWNER1321_EXACT_CONTENT.audit.jsonl.gz',
                'causal_input_indices':[i for i in evidence if i<index],
                'audit_only_post_action_indices':[i for i in evidence if i>index],
                'evidence_messages':[{'index':i,'role':context['messages'][i].get('role'),'sha256':hashlib.sha256(json.dumps(context['messages'][i],ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()} for i in evidence],
                'new_positive_loss_admitted':False,'root_admission_required':True,
            }
            reviews.append(result)
    with gzip.open(OUT/'CONTENT_REVIEW_BATCH02.jsonl.gz','wt',encoding='utf8') as stream:
        for row in reviews: stream.write(json.dumps(row,ensure_ascii=False,separators=(',',':'))+'\n')
    dump(OUT/'REVIEW_PROGRESS.json',{'reviewed_from_original576':len(reviews),'remaining576':576-len(reviews),'episodes':len(REVIEWS),'dispositions':dict(Counter(row['review_disposition'] for row in reviews)),'original_v1_preserved':True,'new_accepted_targets':0,'Teacher_calls':0,'Actor_calls':0,'training_runs':0,'Codex_curation_cost':'UNKNOWN_NOT_ZERO'})
    print(json.dumps({'reviewed':len(reviews),'remaining':576-len(reviews),'episodes':len(REVIEWS)},ensure_ascii=False))

if __name__=='__main__': main()
